using Cameo;
using Xunit;

namespace Cameo.Tests;

/// <summary>Checks ordinary control flow generated by tagged-result propagation.</summary>
public sealed class CameoTryTests
{
    [Theory]
    [InlineData(true)]
    [InlineData(false)]
    public void Propagation_evaluates_once_and_preserves_the_error(bool checking)
    {
        using var engine = new CameoEngine(new CameoRuntimeOptions { TypeCheck = checking });
        var values = engine.RunString("""
            var count = 0
            fn read(pass: boolean) -> Result<integer, boolean> {
                count += 1
                if pass { return ok(42) }
                return err(false)
            }
            fn convert(pass: boolean) -> Result<string, boolean> {
                let number = try read(pass)
                return ok(tostring(number))
            }
            let success = convert(true)
            let failure = convert(false)
            return success:value(), failure:isOk(), failure:issue(), count
            """);
        Assert.Equal("42", values[0].AsString);
        Assert.False(values[1].IsTruthy);
        Assert.True(values[2].IsBoolean);
        Assert.False(values[2].IsTruthy);
        Assert.Equal(2, values[3].I);
    }

    [Fact]
    public void A_function_must_be_able_to_return_the_error()
    {
        using var engine = new CameoEngine();
        var failure = Assert.Throws<CameoCompileException>(() => engine.RunString("""
            fn read() -> Result<integer, string> { return err("failed") }
            fn bad() -> Result<integer, boolean> {
                let value = try read()
                return ok(value)
            }
            return bad()
            """));
        Assert.Contains("propagated error", failure.Message);
    }

    [Theory]
    [InlineData(true)]
    [InlineData(false)]
    public void Catch_recovers_only_the_named_error(bool checking)
    {
        using var engine = new CameoEngine(new CameoRuntimeOptions { TypeCheck = checking });
        var values = engine.RunString("""
            record Problem {
                enum Kind
                    "timeout" "cancelled"
                end
                kind: Kind
            }
            fn read(kind: Problem.Kind) -> Result<string, Problem> {
                return err({kind = kind})
            }
            fn recover(kind: Problem.Kind) -> Result<string, Problem> {
                let report = try read(kind)
                    catch timeout { "cached" }
                return ok(report)
            }
            let cached = recover("timeout")
            let cancelled = recover("cancelled")
            return cached:value(), cancelled:isOk(), cancelled:issue().kind
            """);
        Assert.Equal("cached", values[0].AsString);
        Assert.False(values[1].IsTruthy);
        Assert.Equal("cancelled", values[2].AsString);
    }

    [Fact]
    public void Propagation_closes_resources_in_reverse_order()
    {
        using var engine = new CameoEngine(new CameoRuntimeOptions { TypeCheck = false });
        var values = engine.RunString("""
            let closed: {string} = {}
            local function closer(name)
                return setmetatable({}, { __close = function(_, raised)
                    assert(raised == nil)
                    closed[#closed + 1] = name
                end })
            end
            fn read() -> Result<integer, string> { return err("failed") }
            fn work() -> Result<integer, string> {
                local outer <close> = closer("outer")
                do {
                    local inner <close> = closer("inner")
                    let value = try read()
                    return ok(value)
                }
            }
            let result = work()
            return table.concat(closed, ","), result:issue()
            """);
        Assert.Equal("inner,outer", values[0].AsString);
        Assert.Equal("failed", values[1].AsString);
    }

    [Fact]
    public void Unknown_catch_case_is_rejected()
    {
        using var engine = new CameoEngine();
        var error = Assert.Throws<CameoCompileException>(() => engine.RunString("""
            fn read(job: Future<string>) -> Result<string, FutureError> {
                let value = try Result.fromPair(job.await()) catch missing { "cached" }
                return ok(value)
            }
            return read(Future.completedFuture("live"))
            """));
        Assert.Contains("unknown catch case 'missing'", error.Message);
    }

    [Theory]
    [InlineData(true)]
    [InlineData(false)]
    public void Attempt_can_still_be_an_identifier_at_end_of_line(bool checking)
    {
        using var engine = new CameoEngine(new CameoRuntimeOptions { TypeCheck = checking });
        var values = engine.RunString("""
            let try = 41
            var count = 0
            fn increment() { count += 1 }
            let value = try
            increment()
            return value + count
            """);
        Assert.Equal(42, values[0].I);
    }

    [Fact]
    public void Module_method_edits_do_not_change_the_tag_read_by_try()
    {
        using var engine = new CameoEngine(new CameoRuntimeOptions { TypeCheck = false });
        var values = engine.RunString("""
            Result.isOk = function(_) return false end
            fn read() -> Result<integer, string> { return ok(42) }
            fn convert() -> Result<string, string> {
                let value = try read()
                return ok(tostring(value))
            }
            return convert():value()
            """);
        Assert.Equal("42", values[0].AsString);
    }

    [Theory]
    [InlineData(true)]
    [InlineData(false)]
    public void Pair_adapter_distinguishes_nil_from_false(bool checking)
    {
        using var engine = new CameoEngine(new CameoRuntimeOptions { TypeCheck = checking });
        var values = engine.RunString("""
            let a = Result.fromPair(nil, nil)
            let b = Result.fromPair(42, false)
            return a:isOk(), a:value(), b:isOk(), b:issue()
            """);
        Assert.True(values[0].IsTruthy);
        Assert.True(values[1].IsNil);
        Assert.False(values[2].IsTruthy);
        Assert.True(values[3].IsBoolean);
        Assert.False(values[3].IsTruthy);
    }
}
